package pe.edu.upeu.pago.client; import lombok.RequiredArgsConstructor; import org.slf4j.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.*; @Component @RequiredArgsConstructor public class NotificacionClient { private static final Logger log=LoggerFactory.getLogger(NotificacionClient.class); private final RestClient.Builder builder; public void enviar(Long usuarioId,String tipo,String asunto,String mensaje){ try{builder.build().post().uri("http://kido-notificacion-ms/internal/v1/notificaciones").body(Map.of("usuarioId",usuarioId,"tipo",tipo,"canal","IN_APP","asunto",asunto,"mensaje",mensaje)).retrieve().toBodilessEntity();}catch(Exception e){log.warn("Notificación diferida: {}",e.getMessage());}} }